INSERT INTO clarifications (workspace_id,id,tender_id,bidder_id,oz,question,answer,question_de,answer_de,status) VALUES ('{{WS}}','Q-001','T-2026-014','B-A','01.01','Will the scaffolding from the roofing works still be in place during our works, or do we have to provide our own access?','The scaffolding will be removed on 15 September. Please price your own access equipment.','Bleibt das Gerüst der Dachdeckerarbeiten während unserer Arbeiten stehen, oder müssen wir eigene Zugangstechnik stellen?','Das Gerüst wird am 15. September abgebaut. Bitte kalkulieren Sie eigene Zugangstechnik ein.','answered');
